    "lp.faq1.q": "Tôi không biết lập trình, có dùng được không?",
    "lp.faq1.a": "Được. Bạn chọn sự kiện bắt đầu, thêm từng bước từ danh sách và điền vào các ô có sẵn. Nếu không chắc, hãy mô tả bằng lời để AI soạn bản nháp.",
    "lp.faq2.q": "Weav kết nối với tài khoản của tôi như thế nào?",
    "lp.faq2.a": "Google, Slack và Microsoft dùng màn hình đăng nhập chính thức của họ. Telegram và Discord dùng mã bot hoặc đường dẫn webhook do bạn tạo. Bạn có thể ngắt kết nối bất cứ lúc nào trong mục Không gian làm việc.",
    "lp.faq3.q": "Khi một bước lỗi thì sao?",
    "lp.faq3.a": "Lượt chạy dừng ở bước đó, bạn nhận thông báo kèm lý do bằng lời thường. Sửa xong, bạn chạy lại quy trình.",
    "lp.faq4.q": "Có ứng dụng điện thoại không?",
    "lp.faq4.a": "Có. Ứng dụng di động cho phép xem lượt chạy, nhận thông báo, bật tắt quy trình và quản lý lời mời vào nhóm.",
    "lp.faq5.q": "Weav có giao diện tiếng Anh không?",
    "lp.faq5.a": "Có. Bạn đổi giữa tiếng Việt và tiếng Anh ở góc trên bất cứ lúc nào.",
