    "guide.telegram.title": "How to get a Telegram bot token",
    "guide.telegram.step.1": "Open Telegram, then find and message @BotFather (the official bot with a blue check).",
    "guide.telegram.step.2": "Send /newbot, choose a display name, then a username ending in \"bot\".",
    "guide.telegram.step.3": "BotFather replies with a token like 123456789:AA… — copy it and keep it private.",
    "guide.telegram.step.4": "When adding the Telegram connection, paste the token into the \"Telegram bot token\" field. A bot can serve only one running workflow.",
    "guide.telegram.link": "Open @BotFather",
    "guide.openai.title": "How to get a ChatGPT (OpenAI) API key",
    "guide.openai.step.1": "Open the OpenAI API keys page (button below) and sign in. The account needs some credit.",
    "guide.openai.step.2": "Click Create new secret key, give it a name and create it.",
    "guide.openai.step.3": "Copy the key (starts with sk-) right away because it is shown only once, then paste it into the API key field below. Keep it private.",
    "guide.openai.link": "Open the OpenAI API keys page",
    "guide.anthropic.title": "How to get a Claude (Anthropic) API key",
    "guide.anthropic.step.1": "Open the Anthropic API keys page (button below) and sign in. The account needs some credit.",
    "guide.anthropic.step.2": "Click Create Key, give it a name and click Add.",
    "guide.anthropic.step.3": "Copy the key (starts with sk-ant-) right away because it is shown only once, then paste it into the API key field below. Keep it private.",
    "guide.anthropic.link": "Open the Anthropic API keys page",
    "guide.gemini.title": "How to get a Gemini (Google) API key",
    "guide.gemini.step.1": "Open Google AI Studio (button below) and sign in with your Google account.",
    "guide.gemini.step.2": "Click Create API key, pick a project and create the key.",
    "guide.gemini.step.3": "Copy the key (starts with AIza) and paste it into the API key field below. Keep it private.",
    "guide.gemini.link": "Open Google AI Studio",
    "guide.picture.ai_key": "Your API key",
    "guide.discord.title": "How to get a Discord webhook URL",
    "guide.discord.step.1": "In Discord, hover the channel that should receive messages and click the gear (Edit Channel).",
    "guide.discord.step.2": "Choose Integrations > Webhooks > New Webhook.",
    "guide.discord.step.3": "Name the webhook, then click \"Copy Webhook URL\".",
    "guide.discord.step.4": "When adding the Discord connection, paste the URL into the webhook URL field. It is sent once and never shown again.",
    "guide.discord.link": "Read Discord's guide",
    "guide.slack.title": "How to get a Slack webhook URL",
    "guide.slack.step.1": "Open Slack apps, click Create New App > From scratch and pick your workspace.",
    "guide.slack.step.2": "Open Incoming Webhooks and turn on Activate Incoming Webhooks.",
    "guide.slack.step.3": "Click Add New Webhook to Workspace, pick the channel and click Allow.",
    "guide.slack.step.4": "Copy the https://hooks.slack.com/services/… URL and paste it into the webhook URL field when adding the Slack connection.",
    "guide.slack.link": "Open Slack apps",
    "guide.teams.title": "How to get a Microsoft Teams webhook URL",
    "guide.teams.step.1": "In Teams, open the channel that should receive messages and click ⋯ > Workflows.",
    "guide.teams.step.2": "Pick the template \"Post to a channel when a webhook request is received\".",
    "guide.teams.step.3": "Name it, choose the team and channel, then click Add workflow.",
    "guide.teams.step.4": "Copy the HTTP POST URL Teams shows and paste it into the webhook URL field when adding the Teams connection.",
    "guide.google.title": "How connecting a Google account works",
    "guide.google.step.1": "Name the connection and click Create and connect.",
    "guide.google.step.2": "Google opens its sign-in page: pick your account and click Allow so Weav can use this service.",
    "guide.google.step.3": "You come back to Weav and the connection turns Active.",
    "guide.webhook.title": "How to send data to the webhook",
    "guide.webhook.step.1": "Save and publish the workflow. Weav issues an endpoint key and a secret, shown only once — copy them right away.",
    "guide.webhook.step.2": "In the app that sends data (a form, an app, Zapier…), make a POST request to a URL like the sample below, using your endpoint key.",
    "guide.webhook.step.3": "Add an X-Webhook-Secret header holding the secret, and send a JSON body.",
    "guide.webhook.step.4": "Each request runs the workflow, and later steps can use the JSON fields.",
