    "lp.faq.eyebrow": "Frequently asked questions",
    "lp.faq.h": "Before you start",
    "lp.faq1.q": "I do not know how to code. Can I use it?",
    "lp.faq1.a": "Yes. Pick the starting event, add steps from the list and fill in the boxes. If you are unsure, describe it in words and let AI draft it.",
    "lp.faq2.q": "How does Weav connect to my accounts?",
    "lp.faq2.a": "Google, Slack and Microsoft use their own official sign-in screens. Telegram and Discord use a bot token or webhook link that you create. You can disconnect at any time in Workspace.",
    "lp.faq3.q": "What happens when a step fails?",
    "lp.faq3.a": "The run stops at that step and you get a notification with the reason in plain words. Once fixed, run the workflow again.",
    "lp.faq4.q": "Is there a phone app?",
    "lp.faq4.a": "Yes. The mobile app lets you see runs, get notifications, switch workflows on and off and manage team invitations.",
    "lp.faq5.q": "Is Weav available in English?",
    "lp.faq5.a": "Yes. Switch between Vietnamese and English at the top at any time.",
    "lp.cta.h": "Start with one small task today.",
    "lp.cta.p": "Pick something you do by hand every day and let Weav do it.",
    "lp.cta.signup": "Create an account",
